#!/usr/bin/env python3
"""
Usage:
    python test_models.py models.json

models.json should contain either:
- A JSON list of model names, e.g. ["gpt-4", "gpt-3.5"]
- Or an object with a "models" key that is a list, e.g. {"models": ["gpt-4", "gpt-3.5"]}

This script sends the prompt "Reply with exactly one word: OK" to each model via
an OpenAI-compatible API at http://127.0.0.1:4000/v1/chat/completions.

Requirements implemented:
- Loads model list from JSON file passed on the command line.
- Sends prompt with max_tokens=20 and temperature=0.0 (retries without temperature if rejected).
- 30-second timeout per request.
- Captures model, pass/fail (expects response == "OK" after stripping), latency (s), and first 50 chars of response.
- Prints a formatted table and a summary line.
- Uses only Python standard library.
"""

import sys
import json
import time
import os
import urllib.request
import urllib.error

API_URL = "http://127.0.0.1:4000/v1/chat/completions"
TIMEOUT = 30  # seconds per request
PROMPT = "Reply with exactly one word: OK"
MAX_TOKENS = 20
TEMPERATURE = 0.0
RESPONSE_PREVIEW_LEN = 50


def load_models(path):
    try:
        with open(path, "r", encoding="utf-8") as f:
            data = json.load(f)
    except Exception as e:
        print(f"Failed to read or parse JSON file '{path}': {e}", file=sys.stderr)
        sys.exit(2)

    models = []
    if isinstance(data, list):
        for item in data:
            if isinstance(item, str):
                models.append(item)
            elif isinstance(item, dict):
                name = item.get("name") or item.get("model")
                if isinstance(name, str):
                    models.append(name)
                else:
                    models.append(json.dumps(item))
            else:
                models.append(str(item))
    elif isinstance(data, dict):
        if "models" in data and isinstance(data["models"], list):
            for item in data["models"]:
                if isinstance(item, str):
                    models.append(item)
                elif isinstance(item, dict):
                    name = item.get("name") or item.get("model")
                    if isinstance(name, str):
                        models.append(name)
                    else:
                        models.append(json.dumps(item))
                else:
                    models.append(str(item))
        elif "model" in data and isinstance(data["model"], str):
            models.append(data["model"])
        else:
            # try to extract string values as fallback
            values = [v for v in data.values() if isinstance(v, str)]
            if values:
                models.extend(values)
            else:
                print("JSON must be a list of model names or contain a 'models' list.", file=sys.stderr)
                sys.exit(2)
    else:
        print("JSON root must be a list or an object containing a 'models' list.", file=sys.stderr)
        sys.exit(2)

    # deduplicate while preserving order
    seen = set()
    unique_models = []
    for m in models:
        if m not in seen:
            seen.add(m)
            unique_models.append(m)
    return unique_models


def extract_text_from_body(body_text):
    """
    Try to extract assistant text from a Chat Completions-style response.
    Falls back to returning the raw body text.
    """
    try:
        data = json.loads(body_text)
    except Exception:
        return body_text

    # Standard error field
    if isinstance(data, dict) and "error" in data:
        err = data["error"]
        if isinstance(err, dict):
            return "ERROR: " + str(err.get("message") or err)
        return "ERROR: " + str(err)

    # Standard choices -> message.content
    if isinstance(data, dict) and "choices" in data and isinstance(data["choices"], list) and data["choices"]:
        choice = data["choices"][0]
        if isinstance(choice, dict):
            # chat completion
            msg = choice.get("message")
            if isinstance(msg, dict) and "content" in msg:
                return msg.get("content", "")
            # older style
            if "text" in choice and isinstance(choice["text"], str):
                return choice["text"]
            # streaming delta (not expected for non-streamed response), try 'delta'
            delta = choice.get("delta")
            if isinstance(delta, dict):
                # try a few keys that might hold text
                for k in ("content", "message", "text"):
                    if k in delta:
                        return str(delta[k])
        # fallback: stringify the choice
        try:
            return json.dumps(choice)
        except Exception:
            return str(choice)

    # other possible fields
    for key in ("output", "result", "message"):
        if key in data:
            return str(data[key])

    if isinstance(data, list) and data:
        first = data[0]
        if isinstance(first, str):
            return first
        if isinstance(first, dict):
            for k in ("content", "text", "message"):
                if k in first:
                    return str(first[k])
            try:
                return json.dumps(first)
            except Exception:
                return str(first)

    return body_text


def send_api_request(payload, timeout=TIMEOUT):
    """
    Sends a POST to API_URL with the given JSON payload.
    Returns a tuple: (success: bool, latency_seconds: float, parsed_text: str, raw_body: str)
    On success, parsed_text is extracted assistant text (or full body). On failure parsed_text contains an error summary.
    """
    headers = {"Content-Type": "application/json"}
    api_key = os.environ.get("OPENAI_API_KEY")  # optional
    if api_key:
        headers["Authorization"] = "Bearer " + api_key

    data = json.dumps(payload).encode("utf-8")
    req = urllib.request.Request(API_URL, data=data, headers=headers, method="POST")

    start = time.monotonic()
    try:
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            raw = resp.read().decode("utf-8", errors="replace")
            latency = time.monotonic() - start
            parsed = extract_text_from_body(raw)
            return True, latency, parsed, raw
    except urllib.error.HTTPError as e:
        latency = time.monotonic() - start
        try:
            raw = e.read().decode("utf-8", errors="replace")
        except Exception:
            raw = str(e)
        parsed = extract_text_from_body(raw)
        return False, latency, parsed, raw
    except Exception as e:
        latency = time.monotonic() - start
        raw = str(e)
        return False, latency, raw, raw


def format_response_preview(text, max_len=RESPONSE_PREVIEW_LEN):
    if text is None:
        return ""
    # collapse whitespace/newlines
    cleaned = " ".join(str(text).split())
    if len(cleaned) > max_len:
        return cleaned[:max_len]
    return cleaned


def main():
    if len(sys.argv) < 2:
        print("Usage: python test_models.py models.json", file=sys.stderr)
        sys.exit(1)

    models_file = sys.argv[1]
    models = load_models(models_file)
    if not models:
        print("No models to test.", file=sys.stderr)
        sys.exit(1)

    results = []

    for model in models:
        payload = {
            "model": model,
            "messages": [{"role": "user", "content": PROMPT}],
            "max_tokens": MAX_TOKENS,
            "temperature": TEMPERATURE,
        }

        success, latency, parsed_text, raw_body = send_api_request(payload, timeout=TIMEOUT)

        # If the model/server doesn't support 'temperature', retry without it
        if not success:
            body_lower = (raw_body or "").lower()
            if "temperature" in body_lower:
                payload_no_temp = dict(payload)
                payload_no_temp.pop("temperature", None)
                success, latency, parsed_text, raw_body = send_api_request(payload_no_temp, timeout=TIMEOUT)

        # Determine pass/fail: success AND the assistant reply (stripped) equals exactly "OK"
        passed = False
        if success:
            reply = (parsed_text or "").strip()
            passed = (reply == "OK")

        status = "PASS" if passed else "FAIL"
        preview = format_response_preview(parsed_text or raw_body or "", RESPONSE_PREVIEW_LEN)

        results.append({
            "model": model,
            "status": status,
            "latency": latency,
            "response": preview,
        })

    # Prepare table column widths
    model_col_w = max(len("Model"), max(len(r["model"]) for r in results))
    status_col_w = max(len("Status"), max(len(r["status"]) for r in results))
    latency_strs = [f"{r['latency']:.2f}s" for r in results]
    latency_col_w = max(len("Latency"), max(len(s) for s in latency_strs))
    response_col_w = max(len("Response"), RESPONSE_PREVIEW_LEN)

    total_width = model_col_w + 2 + status_col_w + 2 + latency_col_w + 2 + response_col_w

    # Header
    header = f"{'Model':<{model_col_w}}  {'Status':<{status_col_w}}  {'Latency':>{latency_col_w}}  {'Response'}"
    print(header)
    print("-" * total_width)

    # Rows
    for r, lat_s in zip(results, latency_strs):
        print(f"{r['model']:<{model_col_w}}  {r['status']:<{status_col_w}}  {lat_s:>{latency_col_w}}  {r['response']:<{response_col_w}}")

    # Summary
    total = len(results)
    working = sum(1 for r in results if r["status"] == "PASS")
    failed = total - working
    print()
    print(f"Total: {total} models | ✅ {working} working | ❌ {failed} failed")


if __name__ == "__main__":
    main()
